import type { ActivityContext as RuntimeActivityContext } from 'waf-state-machine';

export interface MediaPlayOperation {
    play(): void;
    playAsync(): Promise<void>;
    stop(): void;
    pause?(): void;
    on?(name: string, callback: (event?: unknown) => void): void;
    off?(name: string, callback: (event?: unknown) => void): void;
}

export interface VideoPlayOperation extends MediaPlayOperation {
    readonly videoElement: HTMLVideoElement;
}

export interface ActivityContext extends RuntimeActivityContext {
    audioCache: Record<string, MediaPlayOperation>;
    videoOperationCache: Record<string, VideoPlayOperation>;
}

export function initializeActivityContext(data: ActivityContext): void {
    Object.assign(data, {
        activeStage: null,
        activeStageId: '',
        activityFinished: false,
        audioCache: {},
        backgroundAssetKey: null,
        hydratedAssetKeys: {},
        hydratingAssetKeys: {},
        sceneElement: null,
        sceneInteractables: [],
        stageState: {},
        videoOperationCache: {},
    });
}

