import type {
    StateMachineEvent,
    StateMachineGuard,
    StateMachineParams,
} from 'waf-state-machine';
import type { ActivityContext } from './context.js';

type SceneEventType =
    | 'CHOICE.SELECTED'
    | 'FEEDBACK.COMPLETED'
    | 'SCENE.COMPLETED'
    | 'SCENE.PRESENTED';

export interface SceneEvent extends StateMachineEvent {
    readonly sceneId: string;
    readonly type: SceneEventType;
}

export function sceneCompleted(sceneId: string): SceneEvent {
    return { sceneId, type: 'SCENE.COMPLETED' };
}

/**
 * Scene transitions configure this guard with `params: { sceneId }` naming
 * the owning top-level scene. `params` keeps the package's StateMachineParams
 * shape so the guard satisfies StateMachineGuard<ActivityContext>;
 * the runtime check keeps a missing or non-string sceneId from matching.
 */
export const isEventForScene: StateMachineGuard<ActivityContext> = (
    { event },
    params: StateMachineParams
) => {
    const sceneId = params.sceneId;
    return typeof sceneId === 'string' && event.sceneId === sceneId;
};

