import type {
    ActivitySceneMetadata,
    StateMachineAction,
    StateMachineParams,
} from 'waf-state-machine';
import { clearRepeatAudio, htmlToElement } from 'waf-utils';
import { hydrateStageAssets } from '../runtime/assets.js';
import { createSceneRoot, disposeInteractables } from '../runtime/dom.js';
import { playAudioKey, resolveMediaAsset, setMediaBackground } from '../runtime/media.js';
import type { ActivityContext } from './context.js';
import { sceneCompleted } from './events.js';

const ACTIVITY_MANAGED_AUDIO_KEYS = new Set<string>();
const RETAINED_VIDEO_SCENE_ATTRIBUTE = 'data-retained-video-scene';

function backgroundMusicAudioKey(scene: ActivitySceneMetadata): string {
    // Background music tracks (e.g. `scene-1-audio-classroom-music`) run on
    // their own: they are started fire-and-forget and never awaited by the
    // scene flow. Finite closing tracks (e.g. `-music-fade`, `-music-outro`)
    // stay in the awaited narration flow.
    return scene.audioKeys.find(
        (key) => /-music$/.test(key) && !/-music-(fade|outro)$/.test(key)
    ) || '';
}

function requiredSceneId(params: StateMachineParams): string {
    if (typeof params.sceneId !== 'string' || params.sceneId.length === 0) {
        throw new Error('State machine action requires params.sceneId.');
    }
    return params.sceneId;
}

function createStagePlaceholderContent(stage: ActivitySceneMetadata): HTMLElement {
    const panel = htmlToElement('<div class="generated-scene__placeholder"></div>');
    const title = htmlToElement('<h2 class="generated-scene__title"></h2>');
    const description = htmlToElement('<p class="generated-scene__description"></p>');
    const assetSummary = htmlToElement('<pre class="generated-scene__assets"></pre>');

    title.textContent = stage.id;
    description.textContent = stage.description;
    assetSummary.textContent = [
        `images: ${stage.imageKeys.join(', ') || '(none)'}`,
        `video: ${stage.videoKeys.join(', ') || '(none)'}`,
        `animations: ${stage.animationKeys.join(', ') || '(none)'}`,
        `audio: ${stage.audioKeys.join(', ') || '(none)'}`,
    ].join('\n');

    panel.appendChild(title);
    panel.appendChild(description);
    panel.appendChild(assetSummary);
    return panel;
}

function sceneClassSlug(sceneId: string): string {
    return sceneId.replace(/[^A-Za-z0-9_-]+/g, '-').toLowerCase();
}

export const presentScene: StateMachineAction<ActivityContext> = async (
    { context, send, signal },
    params
) => {
    const scene = context.sceneCatalog.scene(requiredSceneId(params));
    await hydrateStageAssets(context, scene, ACTIVITY_MANAGED_AUDIO_KEYS);
    if (signal.aborted) {
        return;
    }

    context.activeStage = scene;
    context.activeStageId = scene.id;
    context.backgroundAssetKey = scene.imageKeys[0] || null;
    context.stageState[scene.id] = context.stageState[scene.id] || {};

    renderBackground(context);
    const sceneElement = createSceneRoot(
        `generated-scene generated-scene--${sceneClassSlug(scene.id)}`
    );
    sceneElement.appendChild(createStagePlaceholderContent(scene));
    context.root.appendChild(sceneElement);
    context.sceneElement = sceneElement;

    if (
        scene.videoKeys.length === 0 &&
        params.preserveRetainedVideoScene !== true
    ) {
        removeRetainedVideoScene(context);
    }

    const backgroundAudioKey = backgroundMusicAudioKey(scene);
    if (backgroundAudioKey) {
        void playAudioKey(context, backgroundAudioKey, { signal });
    }

    const narrationAudioKeys = backgroundAudioKey
        ? scene.audioKeys.filter((audioKey) => audioKey !== backgroundAudioKey)
        : scene.audioKeys;
    const audioKey = narrationAudioKeys[0];
    if (audioKey) {
        await playAudioKey(context, audioKey, { signal });
        if (signal.aborted) {
            return;
        }
    }
    send(sceneCompleted(scene.id));
};

function renderBackground(context: ActivityContext): void {
    const backgroundAsset = resolveMediaAsset(context, context.backgroundAssetKey);
    if (backgroundAsset) {
        setMediaBackground(context.root, backgroundAsset);
    }
}

export function removeRetainedVideoScene(context: ActivityContext): void {
    context.root
        .querySelectorAll<HTMLElement>(`[${RETAINED_VIDEO_SCENE_ATTRIBUTE}="true"]`)
        .forEach((scene) => scene.remove());
}

export const cleanupScene: StateMachineAction<ActivityContext> = ({ context }) => {
    clearRepeatAudio();
    disposeInteractables(context.sceneInteractables);
    context.sceneInteractables = [];
    if (context.sceneElement) {
        if (context.sceneElement.querySelector('video')) {
            removeRetainedVideoScene(context);
            context.sceneElement.setAttribute('aria-hidden', 'true');
            context.sceneElement.setAttribute('inert', '');
            context.sceneElement.setAttribute(RETAINED_VIDEO_SCENE_ATTRIBUTE, 'true');
        } else {
            context.sceneElement.remove();
        }
        context.sceneElement = null;
    }
};

export const finalizeActivity: StateMachineAction<ActivityContext> = (args) => {
    cleanupScene(args, {});
    removeRetainedVideoScene(args.context);
    args.context.activityFinished = true;
};

