import pubSubSingleton, { EVENTS } from 'pubsubsingleton';

const PRE_ACTIVITY_START_ITEM_EVENT = 'assessmentItemService:preActivityStart-assessmentItem';
const PRE_ACTIVITY_START_ITEM_LIST_EVENT = 'assessmentItemService:preActivityStart-assessmentItemList';

type AssessmentChoice = {
    id?: string | number;
    isCorrect?: boolean;
    value?: { text?: string | number };
};

type AssessmentItem = {
    itemConfiguration?: { simpleChoice?: AssessmentChoice[] };
    itemScoreId?: string | number;
    title?: string;
};

type AssessmentEventHandler = (...payload: unknown[]) => void;

type AssessmentPubSub = {
    subscribe: (name: string, handler: AssessmentEventHandler) => void;
    publish: (name: string, payload: unknown) => void;
    unsubscribe?: (name: string, handler: AssessmentEventHandler) => void;
    off?: (name: string, handler: AssessmentEventHandler) => void;
};

type AssessmentRuntime = {
    complete: boolean;
    initialized: boolean;
    item: AssessmentItem | null;
    itemKeys: Record<string, true>;
    itemQueue: AssessmentItem[];
    itemWaiter: ((item: AssessmentItem | null) => void) | null;
    onComplete: AssessmentEventHandler | null;
    onItem: AssessmentEventHandler | null;
    onItemList: AssessmentEventHandler | null;
    subscriptions: { name: string; method: AssessmentEventHandler }[];
};

type AssessmentData = {
    assessmentItem?: AssessmentItem | null;
    assessmentPreviewSkipApplied?: boolean;
    assessmentRuntime?: AssessmentRuntime;
    configuration?: Record<string, unknown>;
    pubSub?: AssessmentPubSub;
};

function isRecord(value: unknown): value is Record<string, unknown> {
    return Boolean(value) && typeof value === 'object';
}

function hasPubSubShape(pubSub: unknown): pubSub is AssessmentPubSub {
    const candidate = isRecord(pubSub) ? pubSub : {};
    return (
        typeof candidate.subscribe === 'function' &&
        typeof candidate.publish === 'function'
    );
}

function resolveAssessmentPubSub(data: AssessmentData = {}): AssessmentPubSub {
    if (hasPubSubShape(data.pubSub)) {
        return data.pubSub;
    }

    if (hasPubSubShape(pubSubSingleton.pubSub)) {
        return pubSubSingleton.pubSub;
    }

    throw new Error('Assessment runtime requires an initialized pubSub with subscribe and publish methods.');
}

function extractAssessmentItem(payload: unknown): AssessmentItem | null {
    if (!isRecord(payload)) {
        return null;
    }

    if (payload.itemConfiguration) {
        return payload as AssessmentItem;
    }

    if (isRecord(payload.assessmentItem) && payload.assessmentItem.itemConfiguration) {
        return payload.assessmentItem as AssessmentItem;
    }

    return null;
}

function identifierPart(prefix: string, value: unknown): string {
    return value !== undefined && value !== null
        ? prefix + String(value)
        : '';
}

function assessmentItemKey(item: AssessmentItem | null): string {
    if (!item) {
        return '';
    }

    return identifierPart('score:', item.itemScoreId) ||
        identifierPart('title:', item.title);
}

function assessmentRuntime(data: AssessmentData): AssessmentRuntime {
    const runtime = data.assessmentRuntime;

    if (!runtime || !runtime.initialized) {
        throw new Error('Assessment runtime has not been initialized. Call initializeAssessmentRuntime(data) before waiting for items.');
    }

    return runtime;
}

function resolveAssessmentWaiter(runtime: AssessmentRuntime, value: AssessmentItem | null): void {
    const waiter = runtime.itemWaiter;

    if (!waiter) {
        return;
    }

    runtime.itemWaiter = null;
    runtime.item = value;
    waiter(value);
}

function markItemSeen(runtime: AssessmentRuntime, key: string): boolean {
    if (!key) {
        return false;
    }

    if (runtime.itemKeys[key]) {
        return true;
    }

    runtime.itemKeys[key] = true;
    return false;
}

function enqueueAssessmentItem(runtime: AssessmentRuntime, payload: unknown): boolean {
    const item = extractAssessmentItem(payload);

    if (!item) {
        return false;
    }

    if (markItemSeen(runtime, assessmentItemKey(item))) {
        return true;
    }

    if (runtime.itemWaiter) {
        resolveAssessmentWaiter(runtime, item);
        return true;
    }

    runtime.itemQueue.push(item);
    return true;
}

function enqueueAssessmentItems(runtime: AssessmentRuntime, payloads: unknown): boolean {
    if (!Array.isArray(payloads)) {
        return false;
    }

    return payloads.reduce(
        (hadItem, payload) => enqueueAssessmentItem(runtime, payload) || hadItem,
        false
    );
}

function createAssessmentHandlers(runtime: AssessmentRuntime): void {
    runtime.onItem = (payload: unknown) => {
        if (!enqueueAssessmentItem(runtime, payload)) {
            runtime.complete = true;
            resolveAssessmentWaiter(runtime, null);
        }
    };

    runtime.onItemList = (payloads: unknown) => {
        enqueueAssessmentItems(runtime, payloads);
    };

    runtime.onComplete = () => {
        runtime.complete = true;
        resolveAssessmentWaiter(runtime, null);
    };
}

function assessmentSubscriptions(
    runtime: AssessmentRuntime
): { name: string; method: AssessmentEventHandler }[] {
    return [
        { name: PRE_ACTIVITY_START_ITEM_EVENT, method: runtime.onItem! },
        { name: PRE_ACTIVITY_START_ITEM_LIST_EVENT, method: runtime.onItemList! },
        { name: EVENTS.assessmentItemService.onItem, method: runtime.onItem! },
        { name: EVENTS.assessmentItemService.onItemList, method: runtime.onItemList! },
        { name: EVENTS.assessmentItemService.onComplete, method: runtime.onComplete! },
    ];
}

export function initializeAssessmentRuntime(data: AssessmentData): void {
    const pubSub = resolveAssessmentPubSub(data);

    if (data.assessmentRuntime && data.assessmentRuntime.initialized) {
        return;
    }

    // The machine runtime shallow-copies its context. Keep mutable assessment
    // state behind one shared object so pub/sub callbacks and state actions
    // always observe the same queue, waiter, and completion signal.
    const runtime: AssessmentRuntime = {
        complete: false,
        initialized: false,
        item: null,
        itemKeys: {},
        itemQueue: [],
        itemWaiter: null,
        onComplete: null,
        onItem: null,
        onItemList: null,
        subscriptions: [],
    };
    data.assessmentRuntime = runtime;
    data.assessmentItem = null;

    createAssessmentHandlers(runtime);
    runtime.subscriptions = assessmentSubscriptions(runtime);
    runtime.subscriptions.forEach((subscription) => {
        pubSub.subscribe(subscription.name, subscription.method);
    });

    runtime.initialized = true;
}

export function waitForAssessmentItem(data: AssessmentData): Promise<AssessmentItem | null> {
    const runtime = assessmentRuntime(data);

    if (runtime.itemQueue.length > 0) {
        runtime.item = runtime.itemQueue.shift() || null;
        data.assessmentItem = runtime.item;
        return Promise.resolve(data.assessmentItem);
    }

    if (runtime.complete) {
        runtime.item = null;
        data.assessmentItem = null;
        return Promise.resolve(null);
    }

    if (runtime.itemWaiter) {
        throw new Error('Assessment runtime already has a pending item waiter.');
    }

    return new Promise<AssessmentItem | null>((resolve) => {
        runtime.itemWaiter = resolve;
    }).then((item) => {
        data.assessmentItem = item;
        return item;
    });
}

function hasItemScoreId(item: AssessmentItem | null): item is AssessmentItem {
    return Boolean(
        item &&
        item.itemScoreId !== undefined &&
        item.itemScoreId !== null
    );
}

function hasChoiceId(choice: AssessmentChoice | null): choice is AssessmentChoice {
    return Boolean(choice && choice.id !== undefined && choice.id !== null);
}

function hasChoiceText(
    choice: AssessmentChoice | null
): choice is AssessmentChoice & { value: { text: string | number } } {
    return Boolean(
        choice &&
        choice.value &&
        choice.value.text !== undefined &&
        choice.value.text !== null
    );
}

export function submitSimpleChoiceAssessmentResponse(
    data: AssessmentData,
    item: AssessmentItem | null,
    choice: AssessmentChoice | null
): void {
    const pubSub = resolveAssessmentPubSub(data);

    if (!hasItemScoreId(item)) {
        throw new Error('Assessment item is missing itemScoreId.');
    }

    if (!hasChoiceId(choice)) {
        throw new Error('Assessment choice is missing id.');
    }

    if (!hasChoiceText(choice)) {
        throw new Error('Assessment choice is missing value.text.');
    }

    pubSub.publish(EVENTS.assessmentItemService.submitResponse, [{
        item_score_id: String(item.itemScoreId),
        choice_id: String(choice.id),
        choice_value: String(choice.value.text),
    }]);

    const runtime = assessmentRuntime(data);
    runtime.item = null;
    data.assessmentItem = null;
}

function correctSimpleChoiceForItem(item: AssessmentItem | null): AssessmentChoice {
    if (!item || !item.itemConfiguration) {
        throw new Error('Assessment preview skip received an invalid assessment item.');
    }

    const choices = item.itemConfiguration.simpleChoice;

    if (!Array.isArray(choices)) {
        throw new Error('Assessment preview skip supports SIMPLE_CHOICE items only.');
    }

    const correctChoice = choices.find((choice) => choice && choice.isCorrect === true);

    if (!correctChoice) {
        throw new Error('Assessment preview skip could not find a correct SIMPLE_CHOICE choice.');
    }

    return correctChoice;
}

function previewStartSceneId(data: AssessmentData): string {
    const preview = data.configuration && data.configuration.__loomPreview;
    return isRecord(preview) && typeof preview.startSceneId === 'string'
        ? preview.startSceneId
        : '';
}

function previewSkipRequest(
    data: AssessmentData,
    sceneItemOffsets: Record<string, number | undefined> | undefined
): { skipCount: number } | null {
    const startSceneId = previewStartSceneId(data);

    if (!startSceneId || !sceneItemOffsets) {
        return null;
    }

    if (!Object.prototype.hasOwnProperty.call(sceneItemOffsets, startSceneId)) {
        return null;
    }

    return { skipCount: Number(sceneItemOffsets[startSceneId]) || 0 };
}

async function skipAssessmentItemsForPreview(
    data: AssessmentData,
    sceneItemOffsets: Record<string, number | undefined> | undefined
): Promise<void> {
    const request = previewSkipRequest(data, sceneItemOffsets);

    if (!request || data.assessmentPreviewSkipApplied) {
        return;
    }

    data.assessmentPreviewSkipApplied = true;

    for (let index = 0; index < request.skipCount; index += 1) {
        const item = await waitForAssessmentItem(data);

        if (!item) {
            return;
        }

        submitSimpleChoiceAssessmentResponse(
            data,
            item,
            correctSimpleChoiceForItem(item)
        );
    }
}

export async function alignAssessmentForPreview(
    data: AssessmentData,
    { sceneId, itemOffset }: { sceneId: string; itemOffset: number }
): Promise<void> {
    if (previewStartSceneId(data) !== sceneId) {
        return;
    }
    await skipAssessmentItemsForPreview(data, {
        [sceneId]: itemOffset,
    });
}

export function teardownAssessmentRuntime(data: AssessmentData): void {
    const runtime = data.assessmentRuntime;

    if (!runtime) {
        return;
    }

    const pubSub = resolveAssessmentPubSub(data);
    const subscriptions = runtime.subscriptions || [];

    subscriptions.forEach((subscription) => {
        if (!subscription.method) {
            return;
        }

        if (typeof pubSub.unsubscribe === 'function') {
            pubSub.unsubscribe(subscription.name, subscription.method);
            return;
        }

        if (typeof pubSub.off === 'function') {
            pubSub.off(subscription.name, subscription.method);
        }
    });

    runtime.subscriptions = [];
    runtime.onItem = null;
    runtime.onItemList = null;
    runtime.onComplete = null;
    runtime.itemWaiter = null;
    runtime.initialized = false;
    data.assessmentItem = null;
}

