import type { ActivitySceneMetadata } from 'waf-state-machine';
import type { ActivityContext } from '../activity/context.js';
import { languageCodeFromData } from './media/configuration.js';

function configurationValueAtPath(
    configuration: Record<string, unknown>,
    path: string
): unknown {
    return path.split('.').reduce<unknown>(
        (value, key) => (
            value && typeof value === 'object'
                ? (value as Record<string, unknown>)[key]
                : undefined
        ),
        configuration
    );
}

function selectedLanguageCodes(data: ActivityContext): string[] {
    const languageCode = languageCodeFromData(data);

    return [...new Set([languageCode, 'en-US'])];
}

function hydrationKeyCandidate(data: ActivityContext, assetKey: string): string {
    const configuration = data.configuration || {};
    const candidates = selectedLanguageCodes(data)
        .map((languageCode) => `${languageCode}.${assetKey}`);

    candidates.push(assetKey);

    return candidates.find((candidate) => (
        configurationValueAtPath(configuration, candidate) !== undefined
    )) || assetKey;
}

function stageAssetKeys(
    stageMetadata: ActivitySceneMetadata,
    activityManagedAudioKeys: Set<string>
): string[] {
    return Array.from(new Set([
        ...stageMetadata.imageKeys,
        ...stageMetadata.videoKeys,
        ...stageMetadata.animationKeys,
        ...stageMetadata.audioKeys,
    ].filter(Boolean)))
        .filter((assetKey) => !activityManagedAudioKeys.has(assetKey));
}

function pendingAssetHydrations(
    data: ActivityContext,
    stageMetadata: ActivitySceneMetadata,
    activityManagedAudioKeys: Set<string>
) {
    const hydratedAssetKeys = data.hydratedAssetKeys || {};
    const hydratingAssetKeys = data.hydratingAssetKeys || {};
    const pendingHydrations = new Set<Promise<void>>();
    const assetsToHydrate = stageAssetKeys(stageMetadata, activityManagedAudioKeys)
        .map((assetKey) => ({
            assetKey,
            hydrationKey: hydrationKeyCandidate(data, assetKey),
        }))
        .filter(({ assetKey }) => {
            if (hydratedAssetKeys[assetKey]) {
                return false;
            }

            const existingHydration = hydratingAssetKeys[assetKey];
            if (existingHydration) {
                pendingHydrations.add(existingHydration);
                return false;
            }

            return true;
        });

    return {
        assetsToHydrate,
        hydratedAssetKeys,
        hydratingAssetKeys,
        pendingHydrations,
    };
}

function startAssetHydration(
    data: ActivityContext,
    assetsToHydrate: { assetKey: string; hydrationKey: string }[],
    hydratedAssetKeys: Record<string, boolean>,
    hydratingAssetKeys: Record<string, Promise<void>>
): Promise<void> {
    const hydrationKeys = assetsToHydrate.map(({ hydrationKey }) => hydrationKey);
    const hydrationPromise = Promise.resolve()
        .then(() => data.hydrateSelectedAssets(hydrationKeys))
        .then(() => {
            assetsToHydrate.forEach(({ assetKey }) => {
                hydratedAssetKeys[assetKey] = true;
            });
        })
        .finally(() => {
            assetsToHydrate.forEach(({ assetKey }) => {
                if (hydratingAssetKeys[assetKey] === hydrationPromise) {
                    delete hydratingAssetKeys[assetKey];
                }
            });
        });

    assetsToHydrate.forEach(({ assetKey }) => {
        hydratingAssetKeys[assetKey] = hydrationPromise;
    });

    return hydrationPromise;
}

export async function hydrateStageAssets(
    data: ActivityContext,
    stageMetadata: ActivitySceneMetadata | null,
    activityManagedAudioKeys: Set<string> = new Set()
): Promise<void> {
    if (!data.hydrateSelectedAssets || !stageMetadata) {
        return;
    }

    const {
        assetsToHydrate,
        hydratedAssetKeys,
        hydratingAssetKeys,
        pendingHydrations,
    } = pendingAssetHydrations(data, stageMetadata, activityManagedAudioKeys);

    data.hydratedAssetKeys = hydratedAssetKeys;
    data.hydratingAssetKeys = hydratingAssetKeys;

    if (assetsToHydrate.length > 0) {
        pendingHydrations.add(
            startAssetHydration(data, assetsToHydrate, hydratedAssetKeys, hydratingAssetKeys)
        );
    }

    await Promise.all(Array.from(pendingHydrations));
}

