import {
    createAudioEvents,
    getPlayOperation,
    runInterruptedChains,
    setRepeatAudio,
} from 'waf-utils';
import {
    audioOperationCacheKey,
    cachedAudioOperation,
    type AudioPlaybackSettings,
} from '../operation-cache.js';
import { recordActivityMedia } from 'waf-state-machine';
import {
    defaultConfigurationValue,
    hasValue,
    languageCodeFromData,
    selectedLanguageConfigurationValue,
} from './configuration.js';
import { resolveMediaUrl } from './sources.js';
import type {
    ActivityContext,
    MediaPlayOperation,
} from '../../activity/context.js';

export interface AudioPlaybackOptions extends AudioPlaybackSettings {
    signal?: AbortSignal;
    [key: string]: unknown;
}

export interface InterruptibleAudioPlayback {
    interrupt(reason?: unknown): void;
    promise: Promise<void>;
}

/**
 * Asset-provided audio sources implement only the playback surface they were
 * built with; the media runtime feature-detects each member before use.
 */
export interface PlayableAudioSource {
    play(): void;
    playAsync?(): Promise<void>;
    stop?(): void;
    pause?(): void;
    on?(name: string, callback: (event?: unknown) => void): void;
    off?(name: string, callback: (event?: unknown) => void): void;
}

function audioOptionValue(value: unknown, fallback: number): number {
    return value === undefined || value === null
        ? fallback
        : value as number;
}

export function mediaErrorDetails(error: unknown): { message: string } {
    return {
        message: error && (error as { message?: unknown }).message
            ? String((error as { message: unknown }).message)
            : String(error || 'Unknown media error'),
    };
}

export function hasPlayableInterface(source: unknown): source is PlayableAudioSource {
    if (!source || typeof source !== 'object') {
        return false;
    }

    const candidate = source as Partial<PlayableAudioSource>;
    return typeof candidate.playAsync === 'function' ||
        typeof candidate.play === 'function';
}

function audioSourcePath(source: unknown): string | null {
    if (typeof source === 'string') {
        return source;
    }

    return source && typeof source === 'object' &&
        typeof (source as Record<string, unknown>).customClipUrl === 'string'
        ? (source as Record<string, unknown>).customClipUrl as string
        : null;
}

function pathAudioOperation(
    data: ActivityContext,
    sourcePath: string,
    settings: AudioPlaybackOptions
): MediaPlayOperation {
    const audioPath = resolveMediaUrl(sourcePath);
    const playbackSettings = {
        channel: settings.channel || 'sfx',
        loop: settings.loop === true,
        volume: audioOptionValue(settings.volume, 1),
    };
    const cacheKey = audioOperationCacheKey(audioPath, playbackSettings);

    return cachedAudioOperation(data, cacheKey, () => getPlayOperation({
        audioPaths: audioPath,
        ...playbackSettings,
    }));
}

function playableAudioFromSource(
    data: ActivityContext,
    source: unknown,
    options: AudioPlaybackOptions | undefined
): PlayableAudioSource | null {
    const settings = options || {};

    if (!source) {
        return null;
    }

    if (hasPlayableInterface(source)) {
        return source;
    }

    const sourcePath = audioSourcePath(source);

    return sourcePath === null
        ? null
        : pathAudioOperation(data, sourcePath, settings);
}

export function resolveAudio(
    data: ActivityContext,
    key: string,
    options?: AudioPlaybackOptions
): PlayableAudioSource | null {
    const assets = data.assets || {};
    const configValue = defaultConfigurationValue(data, key);
    const source = hasValue(configValue) ? configValue : assets[key];

    return playableAudioFromSource(data, source, options);
}

function requestSignal(options?: AudioPlaybackOptions): AbortSignal | undefined {
    return options ? options.signal : undefined;
}

function isAborted(signal: AbortSignal | undefined): boolean {
    return Boolean(signal && signal.aborted);
}

function startAudioPlayback(
    data: ActivityContext,
    key: string,
    clip: PlayableAudioSource
): Promise<void> {
    if (typeof clip.playAsync === 'function') {
        const playback = clip.playAsync();

        recordActivityMedia(data, 'audio', key, 'started');
        return playback;
    }

    const events = createAudioEvents(clip);

    clip.play();
    recordActivityMedia(data, 'audio', key, 'started');
    return events.completed;
}

interface AudioPlaybackMonitor {
    aborted: Promise<void>;
    handleAbort(): void;
    markPlaybackStarted(): void;
    wasInterrupted(): boolean;
}

function createAudioPlaybackMonitor(
    data: ActivityContext,
    key: string,
    clip: PlayableAudioSource
): AudioPlaybackMonitor {
    let interrupted = false;
    let playbackStarted = false;
    let resolveAborted: () => void = () => {};

    const aborted = new Promise<void>((resolve) => {
        resolveAborted = resolve;
    });

    return {
        aborted,
        handleAbort() {
            if (interrupted) {
                return;
            }

            interrupted = true;
            if (typeof clip.stop === 'function') {
                clip.stop();
            }
            if (playbackStarted) {
                recordActivityMedia(data, 'audio', key, 'interrupted');
            }
            resolveAborted();
        },
        markPlaybackStarted() {
            playbackStarted = true;
        },
        wasInterrupted() {
            return interrupted;
        },
    };
}

function connectAbortSignal(
    signal: AbortSignal | undefined,
    monitor: AudioPlaybackMonitor
): () => void {
    if (signal) {
        signal.addEventListener('abort', monitor.handleAbort, { once: true });
    }

    return () => {
        if (signal) {
            signal.removeEventListener('abort', monitor.handleAbort);
        }
    };
}

async function raceAudioPlayback(
    data: ActivityContext,
    key: string,
    clip: PlayableAudioSource,
    monitor: AudioPlaybackMonitor
): Promise<void> {
    const playback = startAudioPlayback(data, key, clip);

    monitor.markPlaybackStarted();
    await Promise.race([Promise.resolve(playback), monitor.aborted]);

    if (!monitor.wasInterrupted()) {
        recordActivityMedia(data, 'audio', key, 'completed');
    }
}

function handlePlaybackFailure(
    data: ActivityContext,
    key: string,
    monitor: AudioPlaybackMonitor,
    error: unknown
): void {
    if (monitor.wasInterrupted()) {
        return;
    }

    recordActivityMedia(data, 'audio', key, 'failed', mediaErrorDetails(error));
    throw error;
}

export async function playAudioKey(
    data: ActivityContext,
    key: string,
    options?: AudioPlaybackOptions
): Promise<void> {
    const signal = requestSignal(options);

    if (isAborted(signal)) {
        return;
    }

    const clip = resolveAudio(data, key, options);

    if (!clip) {
        recordActivityMedia(data, 'audio', key, 'unavailable');
        return;
    }

    const monitor = createAudioPlaybackMonitor(data, key, clip);
    const disconnectAbortSignal = connectAbortSignal(signal, monitor);

    try {
        await raceAudioPlayback(data, key, clip, monitor);
    } catch (error) {
        handlePlaybackFailure(data, key, monitor, error);
    } finally {
        disconnectAbortSignal();
    }
}

export function runInterruptibleAudioKey(
    data: ActivityContext,
    key: string,
    options?: AudioPlaybackOptions
): InterruptibleAudioPlayback {
    const clip = resolveAudio(data, key, options);

    if (!clip) {
        recordActivityMedia(data, 'audio', key, 'unavailable');
        return {
            interrupt: () => {},
            promise: Promise.resolve(),
        };
    }

    return runInterruptedChains((onAbort) => {
        let interrupted = false;
        let settled = false;
        const stop = clip.stop?.bind(clip);

        if (stop) {
            onAbort(() => {
                if (settled || interrupted) {
                    return;
                }
                interrupted = true;
                stop();
                recordActivityMedia(data, 'audio', key, 'interrupted');
            });
        }

        let playback: Promise<void>;

        try {
            if (typeof clip.playAsync === 'function') {
                playback = clip.playAsync();
            } else {
                const events = createAudioEvents(clip);

                clip.play();
                playback = events.completed;
            }
            recordActivityMedia(data, 'audio', key, 'started');
        } catch (error) {
            recordActivityMedia(data, 'audio', key, 'failed', mediaErrorDetails(error));
            throw error;
        }

        return Promise.resolve(playback).then(
            () => {
                settled = true;
                if (!interrupted) {
                    recordActivityMedia(data, 'audio', key, 'completed');
                }
            },
            (error: unknown) => {
                settled = true;
                if (!interrupted) {
                    recordActivityMedia(data, 'audio', key, 'failed', mediaErrorDetails(error));
                }
                throw error;
            }
        );
    });
}

function repeatAudioForKey(
    data: ActivityContext,
    key: string
): { languageCode: string; source: unknown } | null {
    const assets = data.assets || {};
    const repeatAudio = selectedLanguageConfigurationValue(data, key);

    if (repeatAudio) {
        return repeatAudio;
    }

    if (hasValue(assets[key])) {
        return {
            languageCode: languageCodeFromData(data),
            source: assets[key],
        };
    }

    return null;
}

function firstNonEmptyString(...values: unknown[]): string {
    const match = values.find((value) => typeof value === 'string' && value.trim());

    return match ? (match as string).trim() : '';
}

function repeatAudioClip(source: unknown): string {
    if (typeof source !== 'object' || source === null) {
        return firstNonEmptyString(source);
    }

    const record = source as Record<string, unknown>;
    return firstNonEmptyString(record.customClipUrl, record.url, record.src);
}

export function setRepeatAudioForKey(data: ActivityContext, key: string): void {
    const repeatAudio = repeatAudioForKey(data, key);

    if (!repeatAudio || !repeatAudio.source) {
        return;
    }

    const clipUrl = repeatAudioClip(repeatAudio.source);

    if (!clipUrl) {
        return;
    }

    setRepeatAudio(clipUrl, repeatAudio.languageCode);
}

