import type { ActivityContext } from '../../activity/context.js';

const DEFAULT_LANGUAGE_CODE = __DEFAULT_LANGUAGE_CODE__;

export function hasValue(value: unknown): boolean {
    return value !== undefined && value !== null;
}

function languageCodeOf(source: unknown): string {
    if (source && typeof source === 'object') {
        const languageCode = (source as Record<string, unknown>).languageCode;
        if (typeof languageCode === 'string' && languageCode) {
            return languageCode;
        }
    }
    return '';
}

export function languageCodeFromData(data: ActivityContext): string {
    return (
        languageCodeOf(data.user)
        || languageCodeOf(data.student)
        || DEFAULT_LANGUAGE_CODE
    );
}

function languageBucket(
    configuration: Record<string, unknown>,
    languageCode: string
): Record<string, unknown> {
    const bucket = configuration[languageCode];

    return bucket && typeof bucket === 'object' && !Array.isArray(bucket)
        ? bucket as Record<string, unknown>
        : {};
}

export function configurationValue(data: ActivityContext, key: string): unknown {
    const configuration = data.configuration || {};
    const selectedLanguage = languageBucket(
        configuration,
        languageCodeFromData(data)
    );
    const defaultLanguage = languageBucket(configuration, DEFAULT_LANGUAGE_CODE);

    if (hasValue(selectedLanguage[key])) {
        return selectedLanguage[key];
    }

    if (hasValue(defaultLanguage[key])) {
        return defaultLanguage[key];
    }

    return hasValue(configuration[key])
        ? configuration[key]
        : null;
}

export function defaultConfigurationValue(data: ActivityContext, key: string): unknown {
    const configuration = data.configuration || {};
    const defaultLanguage = languageBucket(configuration, DEFAULT_LANGUAGE_CODE);

    if (hasValue(defaultLanguage[key])) {
        return defaultLanguage[key];
    }

    return hasValue(configuration[key])
        ? configuration[key]
        : null;
}

function audioSourceIdentifier(source: unknown): string {
    if (typeof source === 'string') {
        return source;
    }

    if (source && typeof source === 'object') {
        const customClipUrl = (source as Record<string, unknown>).customClipUrl;
        if (typeof customClipUrl === 'string') {
            return customClipUrl;
        }
    }

    return '';
}

function audioSourcesMatch(first: unknown, second: unknown): boolean {
    if (first === second) {
        return true;
    }

    const firstIdentifier = audioSourceIdentifier(first);
    const secondIdentifier = audioSourceIdentifier(second);

    return !!firstIdentifier && firstIdentifier === secondIdentifier;
}

function prefersSelectedLanguage(
    selectedLanguageCode: string,
    selectedSource: unknown,
    defaultSource: unknown
): boolean {
    return (
        selectedLanguageCode !== DEFAULT_LANGUAGE_CODE
        && hasValue(selectedSource)
        && !audioSourcesMatch(selectedSource, defaultSource)
    );
}

export function selectedLanguageConfigurationValue(data: ActivityContext, key: string) {
    const configuration = data.configuration || {};
    const selectedLanguageCode = languageCodeFromData(data);
    const selectedSource = languageBucket(configuration, selectedLanguageCode)[key];
    const defaultSource = languageBucket(configuration, DEFAULT_LANGUAGE_CODE)[key];

    if (prefersSelectedLanguage(selectedLanguageCode, selectedSource, defaultSource)) {
        return {
            languageCode: selectedLanguageCode,
            source: selectedSource,
        };
    }

    if (hasValue(defaultSource)) {
        return {
            languageCode: DEFAULT_LANGUAGE_CODE,
            source: defaultSource,
        };
    }

    return hasValue(configuration[key])
        ? {
            languageCode: DEFAULT_LANGUAGE_CODE,
            source: configuration[key],
        }
        : null;
}

