/* global Activity */

import { htmlToElement } from 'waf-utils';
import { configurationValue } from './configuration.js';
import type { ActivityContext } from '../../activity/context.js';

function hasValue(value: unknown): boolean {
    return value !== undefined && value !== null;
}

function imageElementSource(asset: HTMLImageElement): string {
    return asset.currentSrc || asset.src || '';
}

function objectMediaSource(asset: Record<string, unknown>): string {
    const url = asset.url;
    if (typeof url === 'string' && url.trim()) {
        return url.trim();
    }

    const src = asset.src;
    if (typeof src === 'string' && src.trim()) {
        return src.trim();
    }

    return '';
}

export function mediaAssetSource(asset: unknown): string {
    if (!asset) {
        return '';
    }

    if (isResolvedMediaElement(asset)) {
        return imageElementSource(asset);
    }

    if (typeof asset === 'string') {
        return asset.trim();
    }

    return typeof asset === 'object' ? objectMediaSource(asset as Record<string, unknown>) : '';
}

function isResolvedMediaElement(asset: unknown): asset is HTMLImageElement {
    return (
        typeof HTMLImageElement !== 'undefined' &&
        asset instanceof HTMLImageElement
    );
}

function shouldResolveMediaSource(source: string): boolean {
    return !/^https?:\/\//i.test(source) && source.indexOf('data:') !== 0;
}

function activityPathResolver(): ((source: string) => string) | null {
    const urlUtils = typeof Activity !== 'undefined' && Activity.Utils
        ? Activity.Utils.Url
        : null;

    return urlUtils && typeof urlUtils.getPath === 'function'
        ? urlUtils.getPath
        : null;
}

export function resolveMediaUrl(asset: unknown): string {
    const source = mediaAssetSource(asset);

    if (!source || isResolvedMediaElement(asset) || !shouldResolveMediaSource(source)) {
        return source;
    }

    const getPath = activityPathResolver();

    return getPath ? getPath(source) : source;
}

export function resolveMediaAsset(data: ActivityContext, key: string | null): unknown {
    const assets = data.assets || {};

    if (!key) {
        return null;
    }

    const configValue = configurationValue(data, key);

    return hasValue(configValue) ? configValue : assets[key];
}

export function setMediaBackground(element: HTMLElement, asset: unknown): boolean {
    const source = resolveMediaUrl(asset);

    if (!source) {
        return false;
    }

    Object.assign(element.style, {
        backgroundImage: `url(${JSON.stringify(source)})`,
        backgroundSize: 'cover',
    });
    return true;
}

export function createImageElement(asset: unknown, className = ''): HTMLImageElement | null {
    const source = resolveMediaUrl(asset);

    if (!source) {
        return null;
    }

    const image = htmlToElement<HTMLImageElement>('<img alt="" />');

    if (className) {
        image.className = className;
    }

    image.draggable = false;
    image.src = source;

    return image;
}

