import { createAudioEvents, getPlayOperation } from 'waf-utils';
import { recordActivityMedia } from 'waf-state-machine';
import {
    defaultConfigurationValue,
    hasValue,
} from './configuration.js';
import { hasPlayableInterface, mediaErrorDetails } from './audio.js';
import type { PlayableAudioSource } from './audio.js';
import { resolveMediaUrl } from './sources.js';
import type { ActivityContext } from '../../activity/context.js';

type TimedAudioEvent = {
    id: string;
    time: number;
};

export type TimedAudioOptions = {
    events?: unknown;
    onAudioTimeEvent?: (event: TimedAudioEvent) => void;
    [key: string]: unknown;
};

type TimedAudioState = {
    events: TimedAudioEvent[];
    startFallback: () => void;
    suspendFallback: () => void;
    resumeFallback: () => void;
    stopFallback: () => void;
    emit: (event: TimedAudioEvent) => void;
    handleNativeEvent: (event: TimedAudioEvent) => void;
};

type TimedAudioClip = PlayableAudioSource & { __timedAudioState?: TimedAudioState };

function createTimedAudioState(options: TimedAudioOptions = {}): TimedAudioState | null {
    const timedEvents: TimedAudioEvent[] = Array.isArray(options.events)
        ? options.events.filter((event) => event && typeof event.time === 'number')
        : [];

    if (!timedEvents.length || typeof options.onAudioTimeEvent !== 'function') {
        return null;
    }
    const onAudioTimeEvent = options.onAudioTimeEvent;

    const firedEventIds: Record<string, boolean> = {};
    let fallbackActive = true;
    let fallbackElapsedMs = 0;
    let fallbackStartedAt = 0;
    let fallbackTimers: ReturnType<typeof setTimeout>[] = [];
    let fallbackRunning = false;

    function clearFallbackTimers() {
        fallbackTimers.forEach((timer) => clearTimeout(timer));
        fallbackTimers = [];
    }

    function scheduleFallback() {
        if (!fallbackActive || fallbackRunning) {
            return;
        }

        fallbackRunning = true;
        fallbackStartedAt = Date.now() - fallbackElapsedMs;
        fallbackTimers = timedEvents
            .filter((event) => !firedEventIds[event.id])
            .map((event) => setTimeout(() => {
                if (!fallbackActive || !fallbackRunning) {
                    return;
                }

                fallbackElapsedMs = Math.max(fallbackElapsedMs, event.time);
                timedAudioState.emit(event);
            }, Math.max(0, event.time - fallbackElapsedMs)));
    }

    const timedAudioState: TimedAudioState = {
        events: timedEvents.map((event) => ({
            id: event.id,
            time: event.time,
        })),
        startFallback() {
            scheduleFallback();
        },
        suspendFallback() {
            if (!fallbackRunning) {
                return;
            }

            fallbackElapsedMs = Date.now() - fallbackStartedAt;
            fallbackRunning = false;
            clearFallbackTimers();
        },
        resumeFallback() {
            scheduleFallback();
        },
        stopFallback() {
            fallbackActive = false;
            fallbackRunning = false;
            clearFallbackTimers();
        },
        emit(event) {
            if (!event || firedEventIds[event.id]) {
                return;
            }

            firedEventIds[event.id] = true;
            onAudioTimeEvent({
                id: event.id,
                time: event.time,
            });
        },
        handleNativeEvent(event) {
            if (!event) {
                return;
            }

            if (event.id) {
                firedEventIds[event.id] = true;
            }

            onAudioTimeEvent(event);
        },
    };

    return timedAudioState;
}

function attachTimedAudioFallback(clip: TimedAudioClip | null | undefined): () => void {
    const timedAudioState = clip && clip.__timedAudioState;

    if (!timedAudioState || !timedAudioState.events.length) {
        return () => {};
    }

    if (typeof clip.on === 'function') {
        const onStarted = () => {
            timedAudioState.startFallback();
        };
        const onCompleted = () => {
            timedAudioState.stopFallback();
        };

        clip.on('started', onStarted);
        clip.on('completed', onCompleted);

        return () => {
            timedAudioState.stopFallback();

            if (typeof clip.off === 'function') {
                clip.off('started', onStarted);
                clip.off('completed', onCompleted);
            }
        };
    }

    timedAudioState.startFallback();

    return () => {
        timedAudioState.stopFallback();
    };
}

function timedAudioAssetSource(data: ActivityContext, key: string): unknown {
    const assets = data.assets || {};
    const configValue = defaultConfigurationValue(data, key);

    return hasValue(configValue) ? configValue : assets[key];
}

function timedAudioPathFromSource(source: unknown): string | null {
    if (typeof source === 'string') {
        return source;
    }

    return source && typeof source === 'object' &&
        typeof (source as Record<string, unknown>).customClipUrl === 'string'
        ? (source as Record<string, unknown>).customClipUrl as string
        : null;
}

function timedAudioClipOperation(
    audioPath: string,
    options: TimedAudioOptions,
    timedAudioState: TimedAudioState | null
): TimedAudioClip {
    const clip: TimedAudioClip = getPlayOperation({
        audioPaths: resolveMediaUrl(audioPath),
        channel: 'sfx',
        ...options,
        onAudioTimeEvent: timedAudioState
            ? (event: TimedAudioEvent) => timedAudioState.handleNativeEvent(event)
            : options.onAudioTimeEvent,
    });

    if (timedAudioState) {
        clip.__timedAudioState = timedAudioState;
    }

    return clip;
}

export function createTimedAudioOperation(
    data: ActivityContext,
    key: string,
    options: TimedAudioOptions = {}
): TimedAudioClip | null {
    const source = timedAudioAssetSource(data, key);
    const timedAudioState = createTimedAudioState(options);
    const audioPath = source ? timedAudioPathFromSource(source) : null;

    if (audioPath !== null) {
        return timedAudioClipOperation(audioPath, options, timedAudioState);
    }

    return source && hasPlayableInterface(source) ? source : null;
}

function recordTimedAudio(data: ActivityContext, key: string, status: string): void {
    if (!data || !key) {
        return;
    }

    recordActivityMedia(data, 'audio', key, status);
}

async function playTimedAudioClip(
    clip: TimedAudioClip,
    data: ActivityContext,
    key: string
): Promise<void> {
    if (typeof clip.playAsync === 'function' && typeof clip.on !== 'function') {
        const playback = clip.playAsync();

        recordTimedAudio(data, key, 'started');
        await playback;
    } else {
        const events = createAudioEvents(clip);

        clip.play();
        recordTimedAudio(data, key, 'started');
        await events.completed;
    }

    recordTimedAudio(data, key, 'completed');
}

export async function playTimedAudioOperation(
    clip: TimedAudioClip | null,
    data: ActivityContext,
    key: string
): Promise<void> {
    if (!clip) {
        recordTimedAudio(data, key, 'unavailable');
        return;
    }

    const detachTimedAudioFallback = attachTimedAudioFallback(clip);

    try {
        await playTimedAudioClip(clip, data, key);
    } catch (error) {
        if (data && key) {
            recordActivityMedia(data, 'audio', key, 'failed', mediaErrorDetails(error));
        }
        throw error;
    } finally {
        detachTimedAudioFallback();
    }
}

export function suspendTimedAudioTiming(clip: TimedAudioClip | null): void {
    if (!clip) {
        return;
    }

    if (clip.__timedAudioState) {
        clip.__timedAudioState.suspendFallback();
    }
}

export function resumeTimedAudioTiming(clip: TimedAudioClip | null): void {
    if (!clip) {
        return;
    }

    if (clip.__timedAudioState) {
        clip.__timedAudioState.resumeFallback();
    }
}

export function pauseTimedAudioOperation(clip: TimedAudioClip | null): void {
    if (!clip) {
        return;
    }

    suspendTimedAudioTiming(clip);

    if (typeof clip.pause === 'function') {
        clip.pause();
    }
}

export function resumeTimedAudioOperation(clip: TimedAudioClip | null): void {
    if (!clip) {
        return;
    }

    if (typeof clip.play === 'function') {
        clip.play();
    }

    resumeTimedAudioTiming(clip);
}

export async function playTimedAudioKey(
    data: ActivityContext,
    key: string,
    options: TimedAudioOptions = {}
): Promise<void> {
    const clip = createTimedAudioOperation(data, key, options);

    return playTimedAudioOperation(clip, data, key);
}

