import { getVideoPlayOperation } from 'waf-utils';
import { recordActivityMedia } from 'waf-state-machine';
import { mediaErrorDetails } from './audio.js';
import { resolveMediaAsset, resolveMediaUrl } from './sources.js';
import type {
    ActivityContext,
    VideoPlayOperation,
} from '../../activity/context.js';

type VideoOperationOptions = {
    channel?: string;
    posterKey?: string;
};

function applyVideoElementAttributes(operation: VideoPlayOperation, poster: string): void {
    operation.videoElement.setAttribute('playsinline', '');
    operation.videoElement.setAttribute('preload', 'auto');

    if (poster) {
        operation.videoElement.setAttribute('poster', poster);
    } else {
        operation.videoElement.removeAttribute('poster');
    }
}

export function createVideoOperation(
    data: ActivityContext,
    key: string,
    options: VideoOperationOptions = {}
): VideoPlayOperation | null {
    const video = resolveMediaUrl(resolveMediaAsset(data, key));
    const poster = options.posterKey
        ? resolveMediaUrl(resolveMediaAsset(data, options.posterKey))
        : '';

    if (!video) {
        return null;
    }

    const channel = options.channel || 'vocals';
    const cacheKey = channel + ':' + video;
    const videoOperationCache = data.videoOperationCache || {};
    const operation = videoOperationCache[cacheKey] || getVideoPlayOperation({
        video,
        channel,
    });

    videoOperationCache[cacheKey] = operation;
    data.videoOperationCache = videoOperationCache;

    applyVideoElementAttributes(operation, poster);

    return operation;
}

export function waitForVideoReady(videoElement: HTMLVideoElement): Promise<void> {
    if (videoElement.error) {
        return Promise.reject(videoElement.error);
    }

    if (videoElement.readyState >= 2) {
        return Promise.resolve();
    }

    return new Promise<void>((resolve, reject) => {
        function cleanup() {
            videoElement.removeEventListener('canplay', handleReady);
            videoElement.removeEventListener('error', handleError);
            videoElement.removeEventListener('loadeddata', handleReady);
            videoElement.removeEventListener('seeked', handleReady);
        }

        function handleReady() {
            if (videoElement.readyState < 2) {
                return;
            }
            cleanup();
            resolve();
        }

        function handleError() {
            cleanup();
            reject(videoElement.error);
        }

        videoElement.addEventListener('canplay', handleReady);
        videoElement.addEventListener('error', handleError);
        videoElement.addEventListener('loadeddata', handleReady);
        videoElement.addEventListener('seeked', handleReady);
        handleReady();
    });
}

export function waitForVideoPlaying(videoElement: HTMLVideoElement): Promise<void> {
    if (videoElement.error) {
        return Promise.reject(videoElement.error);
    }

    if (
        !videoElement.paused &&
        !videoElement.ended &&
        videoElement.readyState >= 3
    ) {
        return Promise.resolve();
    }

    return new Promise<void>((resolve, reject) => {
        function cleanup() {
            videoElement.removeEventListener('playing', handlePlaying);
            videoElement.removeEventListener('error', handleError);
        }

        function handlePlaying() {
            cleanup();
            resolve();
        }

        function handleError() {
            cleanup();
            reject(videoElement.error);
        }

        videoElement.addEventListener('playing', handlePlaying, { once: true });
        videoElement.addEventListener('error', handleError, { once: true });
    });
}

export async function playVideoOperation(
    data: ActivityContext,
    key: string,
    operation: VideoPlayOperation | null
): Promise<void> {
    if (!operation || !operation.videoElement) {
        recordActivityMedia(data, 'video', key, 'unavailable');
        return;
    }

    try {
        await waitForVideoReady(operation.videoElement);
        recordActivityMedia(data, 'video', key, 'ready');
        const playing = waitForVideoPlaying(operation.videoElement).then(() => {
            recordActivityMedia(data, 'video', key, 'started');
        });

        await Promise.all([playing, operation.playAsync()]);
        recordActivityMedia(data, 'video', key, 'completed');
    } catch (error) {
        recordActivityMedia(data, 'video', key, 'failed', mediaErrorDetails(error));
        throw error;
    }
}

