import type {
    ActivityContext,
    MediaPlayOperation,
} from '../activity/context.js';

export interface AudioPlaybackSettings {
    channel?: string;
    loop?: boolean;
    volume?: number;
}

export function audioOperationCacheKey(
    resolvedSource: string,
    playbackSettings: AudioPlaybackSettings
): string {
    return [
        resolvedSource,
        playbackSettings.channel,
        playbackSettings.loop ? 'loop' : 'once',
        playbackSettings.volume,
    ].join(':');
}

export function cachedAudioOperation(
    data: ActivityContext,
    cacheKey: string,
    createOperation: () => MediaPlayOperation
): MediaPlayOperation {
    const audioCache = data.audioCache || {};

    if (!audioCache[cacheKey]) {
        audioCache[cacheKey] = createOperation();
        data.audioCache = audioCache;
    }

    return audioCache[cacheKey];
}

